import { Font } from "@react-pdf/renderer";

/**
 * Embedded fonts for the contacts PDF document.
 *
 * react-pdf's default fonts (Helvetica etc.) are non-embedded base-14 fonts
 * with no ToUnicode map — some viewers can display but not select, search or
 * copy such text, and characters outside WinAnsi encoding (e.g. "Nguyễn",
 * "Łukaszewicz") are written with wrong byte values and print garbled.
 * Embedding a real font produces a ToUnicode CMap and proper glyph coverage,
 * making all text selectable/highlightable and correctly rendered.
 *
 * Source: Liberation Sans 2.1.5 (https://github.com/liberationfonts/liberation-fonts)
 * License: SIL Open Font License 1.1 — metric-compatible with Arial/Helvetica.
 * Subset: Latin (incl. Extended/Vietnamese), Greek, Cyrillic, general
 * punctuation and ligatures.
 */
const REGULAR =
  "data:font/ttf;base64,";

const BOLD =
  "data:font/ttf;base64,";

export const CONTACTS_PDF_FONT_FAMILY = "Liberation Sans";

Font.register({
  family: CONTACTS_PDF_FONT_FAMILY,
  fonts: [{ src: REGULAR }, { src: BOLD, fontWeight: "bold" }],
});
